INSERT INTO public.posts (id, title, subtitle, slug, author, category, cover_url, body, seo_title, meta_description, status, published_at, created_at, updated_at) VALUES ('1e18e06a-f690-48fd-87a1-acd27baa9e3f', 'Check-up de rotina: quando fazer e por que ele importa', 'Entenda como consultas e exames periódicos ajudam a prevenir problemas de saúde antes que apareçam.', 'check-up-de-rotina-quando-fazer', 'Equipe VivaMed', 'Prevenção', '/images/blog-checkup.jpg', '<p>Muita gente só procura um médico quando já está sentindo alguma coisa. O check-up de rotina existe justamente para mudar esse hábito: ele permite acompanhar a saúde de forma contínua e identificar alterações cedo, quando o cuidado costuma ser mais simples.</p><h2>O que é um check-up?</h2><p>É uma avaliação periódica que pode incluir consulta clínica, medição de pressão, exames de sangue e outros exames indicados conforme idade, histórico familiar e estilo de vida. Não existe um pacote único para todo mundo — o ideal é que o médico indique o que faz sentido para você.</p><h2>Com que frequência fazer?</h2><p>Para adultos saudáveis, uma avaliação anual é uma referência comum. Pessoas com condições crônicas, histórico familiar de doenças ou em acompanhamento específico podem precisar de intervalos menores, sempre com orientação profissional.</p><h2>Por que vale a pena?</h2><ul><li>Detecta alterações como pressão alta e colesterol antes dos sintomas;</li><li>Ajuda a manter vacinas e exames preventivos em dia;</li><li>Cria um histórico de saúde que facilita futuras consultas;</li><li>Dá mais tranquilidade no dia a dia.</li></ul><h2>Onde fazer em Nova Iguaçu?</h2><p>Na VivaMed, em Comendador Soares, você encontra consultas médicas e exames laboratoriais em um só lugar. Fale com a nossa equipe pelo WhatsApp e agende seu atendimento.</p><p><em>Este conteúdo é informativo e não substitui a avaliação de um profissional de saúde.</em></p>', 'Check-up de rotina: quando fazer e por que importa | VivaMed Nova Iguaçu', 'Saiba quando fazer um check-up de rotina, o que ele inclui e por que a prevenção é o melhor cuidado. Consultas e exames em Nova Iguaçu - RJ.', 'published', '2026-10-10 14:00:56.920862+00', '2026-10-10 14:00:56.920862+00', '2026-11-03 13:21:19.220853+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts (id, title, subtitle, slug, author, category, cover_url, body, seo_title, meta_description, status, published_at, created_at, updated_at) VALUES ('2564decc-e05f-4769-8e5c-85eafb7e0196', 'Saúde bucal: 5 cuidados simples que fazem diferença', 'Escovação correta, fio dental e visitas ao dentista: veja hábitos que protegem seu sorriso.', 'saude-bucal-5-cuidados-simples', 'Equipe VivaMed', 'Odontologia', '/images/blog-saude-bucal.jpg', '<p>A saúde bucal vai muito além de um sorriso bonito. Cáries, gengivite e mau hálito costumam começar de forma silenciosa, e a prevenção é sempre mais simples — e mais barata — do que o tratamento.</p><h2>1. Escove os dentes ao menos duas vezes ao dia</h2><p>Use creme dental com flúor e escove por cerca de dois minutos, sem esquecer a língua. A escovação antes de dormir é a mais importante do dia.</p><h2>2. Não pule o fio dental</h2><p>A escova não alcança o espaço entre os dentes. O fio dental diário remove resíduos que causam cáries e inflamação na gengiva.</p><h2>3. Troque a escova regularmente</h2><p>A cada três meses, ou antes se as cerdas estiverem deformadas. Escovas gastas limpam mal e podem machucar a gengiva.</p><h2>4. Cuide da alimentação</h2><p>Reduza açúcares entre as refeições e beba água ao longo do dia. Açúcar frequente é o maior aliado da cárie.</p><h2>5. Visite o dentista regularmente</h2><p>Mesmo sem dor, uma avaliação a cada seis meses ajuda a encontrar problemas no início e manter a limpeza profissional em dia.</p><h2>Odontologia em Nova Iguaçu</h2><p>A VivaMed conta com atendimento odontológico em Comendador Soares. Agende sua avaliação pelo WhatsApp.</p><p><em>Este conteúdo é informativo e não substitui a avaliação de um dentista.</em></p>', 'Saúde bucal: 5 cuidados simples que fazem diferença | VivaMed', 'Escovação, fio dental e dentista em dia: confira 5 cuidados simples para manter a saúde bucal. Odontologia em Nova Iguaçu - RJ.', 'published', '2026-10-10 14:00:56.920862+00', '2026-10-10 14:00:56.920862+00', '2026-11-03 13:21:19.220853+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts (id, title, subtitle, slug, author, category, cover_url, body, seo_title, meta_description, status, published_at, created_at, updated_at) VALUES ('363114e8-8dab-48b1-b0b6-1c11333237a1', 'Exames preventivos: o que são e por que fazer', 'Exames de sangue, pressão e outros acompanhamentos simples ajudam a cuidar da saúde antes dos sintomas.', 'exames-preventivos-o-que-sao', 'Equipe VivaMed', 'Exames', '/images/blog-exames.jpg', '<p>Exames preventivos são aqueles feitos mesmo quando não há sintomas. A ideia é simples: descobrir cedo o que pode se tornar um problema no futuro.</p><h2>Quais exames costumam fazer parte da prevenção?</h2><p>Depende de idade, sexo e histórico de cada pessoa, mas alguns exemplos comuns incluem:</p><ul><li>Hemograma e exames de sangue (glicose, colesterol);</li><li>Medição de pressão arterial;</li><li>Exames de rotina indicados por faixa etária;</li><li>Avaliações específicas conforme histórico familiar.</li></ul><h2>Quem deve fazer?</h2><p>Todo mundo se beneficia de algum acompanhamento. Adultos acima dos 40 anos, pessoas com histórico familiar de diabetes, hipertensão ou doenças cardíacas e quem tem condições crônicas devem conversar com um médico sobre a frequência ideal.</p><h2>Praticidade importa</h2><p>Fazer exames no mesmo lugar onde você consulta economiza tempo e facilita o acompanhamento dos resultados. Na VivaMed, em Nova Iguaçu, você realiza exames laboratoriais com praticidade. Consulte os exames disponíveis pelo WhatsApp.</p><p><em>Este conteúdo é informativo e não substitui a orientação de um profissional de saúde.</em></p>', 'Exames preventivos: o que são e por que fazer | VivaMed Nova Iguaçu', 'Entenda o que são exames preventivos, quem deve fazer e com que frequência. Exames laboratoriais em Nova Iguaçu - RJ.', 'published', '2026-10-10 14:00:56.920862+00', '2026-10-10 14:00:56.920862+00', '2026-11-03 13:21:19.220853+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts (id, title, subtitle, slug, author, category, cover_url, body, seo_title, meta_description, status, published_at, created_at, updated_at) VALUES ('a53c42d5-e7c5-4f84-924b-4ebe1c84eaa0', 'Rotina de saúde equilibrada: por onde começar', 'Sono, alimentação, movimento e acompanhamento médico: pequenas mudanças que somam muito.', 'rotina-de-saude-equilibrada-por-onde-comecar', 'Equipe VivaMed', 'Bem-estar', '/images/blog-rotina-saudavel.jpg', '<p>Cuidar da saúde não precisa ser complicado. Na maioria das vezes, o que faz diferença é a constância em hábitos simples — não mudanças radicais que duram uma semana.</p><h2>Sono em primeiro lugar</h2><p>Dormir bem regula energia, humor e imunidade. Tente manter horários regulares e reduzir telas antes de deitar.</p><h2>Movimento todos os dias</h2><p>Não precisa ser academia: caminhadas de 30 minutos já trazem benefícios para coração, peso e saúde mental. O importante é não passar o dia inteiro parado.</p><h2>Alimentação sem terrorismo</h2><p>Mais comida de verdade — frutas, verduras, grãos — e menos ultraprocessados. Pequenas trocas consistentes valem mais que dietas restritivas.</p><h2>Água e pausas</h2><p>Hidratação e pequenas pausas ao longo do trabalho ajudam corpo e mente a funcionarem melhor.</p><h2>Acompanhamento profissional</h2><p>Hábitos bons não substituem consultas e exames de rotina. Manter o acompanhamento em dia é parte da rotina de saúde. A VivaMed, em Comendador Soares, Nova Iguaçu, está perto de você para isso — agende pelo WhatsApp.</p><p><em>Este conteúdo é informativo e não substitui a avaliação de um profissional de saúde.</em></p>', 'Rotina de saúde equilibrada: por onde começar | VivaMed', 'Sono, movimento, alimentação e acompanhamento médico: veja como montar uma rotina de saúde equilibrada. Clínica em Nova Iguaçu - RJ.', 'published', '2026-10-10 14:00:56.920862+00', '2026-10-10 14:00:56.920862+00', '2026-11-03 13:21:19.220853+00') ON CONFLICT (id) DO NOTHING;
